-- DP-171 (ADR-022): content proposals and their company review.
--
-- Runs as dp_owner (ADR-012A). Additive only: two enums, two tables, CHECK constraints, guard
-- triggers and privileges. No existing column or row changes. A proposal holds research-drafted
-- listing text for one product on one site; it never writes to Product, ProductSiteListing,
-- ProductListingText, specifications, images, documents or publications, and approving it is
-- neither a technical approval (PM-3) nor a publication.
--
-- Part 1 is generated by `prisma migrate diff --from-schema <main> --to-schema schema.prisma`.
-- Part 2 adds the rules Prisma cannot model; test/integration/catalog-workflow.int.test.ts
-- (section 10) covers each one. Both tables are site-bound in the site-scoped client and have no
-- row-level security (catalogue tables, like CmsPage: ADR-020 D5).

-- ===========================================================================================
-- Part 0: preconditions
-- ===========================================================================================

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dp_app') THEN
    RAISE EXCEPTION 'DP-171: role dp_app missing; ADR-012A must be applied first';
  END IF;
  IF to_regclass('public."ProductSiteListing"') IS NULL THEN
    RAISE EXCEPTION 'DP-171: the product catalogue (PM-1) must be applied first';
  END IF;
END $$;

-- ===========================================================================================
-- Part 1: enums, tables and indexes (generated)
-- ===========================================================================================

-- CreateEnum
CREATE TYPE "ProductContentProposalStatus" AS ENUM ('REVIEW_PENDING', 'CHANGES_REQUESTED', 'APPROVED');

-- CreateEnum
CREATE TYPE "ProductContentProposalAction" AS ENUM ('CREATED', 'REVISED', 'APPROVED', 'CHANGES_REQUESTED');

-- CreateTable
CREATE TABLE "ProductContentProposal" (
    "id" UUID NOT NULL,
    "productId" UUID NOT NULL,
    "siteId" UUID NOT NULL,
    "locale" VARCHAR(35) NOT NULL,
    "proposedSummary" VARCHAR(500),
    "proposedDescription" TEXT,
    "reviewData" JSONB NOT NULL,
    "sourceRef" VARCHAR(200) NOT NULL,
    "sourceSha256" CHAR(64) NOT NULL,
    "status" "ProductContentProposalStatus" NOT NULL DEFAULT 'REVIEW_PENDING',
    "version" INTEGER NOT NULL DEFAULT 1,
    "authorIds" UUID[] DEFAULT ARRAY[]::UUID[],
    "decidedAt" TIMESTAMPTZ(3),
    "decidedById" UUID,
    "createdById" UUID NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "ProductContentProposal_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "ProductContentProposalEvent" (
    "id" UUID NOT NULL,
    "proposalId" UUID NOT NULL,
    "siteId" UUID NOT NULL,
    "action" "ProductContentProposalAction" NOT NULL,
    "proposalVersion" INTEGER NOT NULL,
    "actorUserId" UUID NOT NULL,
    "comment" VARCHAR(2000),
    "contentSha256" CHAR(64) NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "ProductContentProposalEvent_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "ProductContentProposal_siteId_status_idx" ON "ProductContentProposal"("siteId", "status");

-- CreateIndex
CREATE UNIQUE INDEX "ProductContentProposal_productId_siteId_locale_key" ON "ProductContentProposal"("productId", "siteId", "locale");

-- CreateIndex
CREATE UNIQUE INDEX "ProductContentProposal_id_siteId_key" ON "ProductContentProposal"("id", "siteId");

-- CreateIndex
CREATE INDEX "ProductContentProposalEvent_proposalId_createdAt_idx" ON "ProductContentProposalEvent"("proposalId", "createdAt");

-- CreateIndex
CREATE INDEX "ProductContentProposalEvent_siteId_createdAt_idx" ON "ProductContentProposalEvent"("siteId", "createdAt");

-- AddForeignKey
ALTER TABLE "ProductContentProposal" ADD CONSTRAINT "ProductContentProposal_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposal" ADD CONSTRAINT "ProductContentProposal_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposal" ADD CONSTRAINT "ProductContentProposal_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposal" ADD CONSTRAINT "ProductContentProposal_decidedById_fkey" FOREIGN KEY ("decidedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposalEvent" ADD CONSTRAINT "ProductContentProposalEvent_proposalId_siteId_fkey" FOREIGN KEY ("proposalId", "siteId") REFERENCES "ProductContentProposal"("id", "siteId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposalEvent" ADD CONSTRAINT "ProductContentProposalEvent_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "ProductContentProposalEvent" ADD CONSTRAINT "ProductContentProposalEvent_actorUserId_fkey" FOREIGN KEY ("actorUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ===========================================================================================
-- Part 2: formats, state rules, separation of duties, append-only history
-- ===========================================================================================

ALTER TABLE "ProductContentProposal"
  ADD CONSTRAINT "ProductContentProposal_locale_format"
    CHECK ("locale" ~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$'),
  ADD CONSTRAINT "ProductContentProposal_summary_trimmed" CHECK (
    "proposedSummary" IS NULL OR ("proposedSummary" = btrim("proposedSummary") AND "proposedSummary" <> '')
  ),
  ADD CONSTRAINT "ProductContentProposal_description_format" CHECK (
    "proposedDescription" IS NULL OR (
      "proposedDescription" = btrim("proposedDescription")
      AND "proposedDescription" <> ''
      AND char_length("proposedDescription") <= 8000
    )
  ),
  -- Internal review notes ("[CONFIRM ...]") never sit in customer-facing text.
  ADD CONSTRAINT "ProductContentProposal_text_no_review_markers" CHECK (
    coalesce("proposedSummary", '') !~* '\[confirm' AND coalesce("proposedDescription", '') !~* '\[confirm'
  ),
  ADD CONSTRAINT "ProductContentProposal_review_data_object" CHECK (jsonb_typeof("reviewData") = 'object'),
  ADD CONSTRAINT "ProductContentProposal_source_ref_trimmed"
    CHECK ("sourceRef" = btrim("sourceRef") AND "sourceRef" <> ''),
  ADD CONSTRAINT "ProductContentProposal_source_sha256_hex" CHECK ("sourceSha256" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "ProductContentProposal_version_positive" CHECK ("version" >= 1),
  ADD CONSTRAINT "ProductContentProposal_author_ids_present" CHECK ("authorIds" IS NOT NULL),
  -- A decision carries who and when; a pending proposal carries neither.
  ADD CONSTRAINT "ProductContentProposal_decision_fields" CHECK (
    ("status" = 'REVIEW_PENDING') = ("decidedAt" IS NULL)
    AND ("decidedAt" IS NULL) = ("decidedById" IS NULL)
  );

ALTER TABLE "ProductContentProposalEvent"
  ADD CONSTRAINT "ProductContentProposalEvent_version_positive" CHECK ("proposalVersion" >= 1),
  ADD CONSTRAINT "ProductContentProposalEvent_content_sha256_hex" CHECK ("contentSha256" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "ProductContentProposalEvent_comment_trimmed"
    CHECK ("comment" IS NULL OR ("comment" = btrim("comment") AND "comment" <> '')),
  -- A request for changes always says why.
  ADD CONSTRAINT "ProductContentProposalEvent_changes_need_comment"
    CHECK ("action" <> 'CHANGES_REQUESTED' OR "comment" IS NOT NULL);

-- State rules on every write, for every role:
--  * product, site, locale, creator and source never change;
--  * a revision (new or unchanged content, e.g. a resubmission) is version + 1 in REVIEW_PENDING;
--    a content change is always a revision;
--  * a decision (APPROVED / CHANGES_REQUESTED) is taken only on a pending proposal, without a
--    content change, by someone who did not write the revision (separation of duties).
CREATE FUNCTION catalog_content_proposal_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  content_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'REVIEW_PENDING' OR NEW."version" <> 1 THEN
      RAISE EXCEPTION 'catalog: a new proposal starts as REVIEW_PENDING version 1'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT (NEW."createdById" = ANY (NEW."authorIds")) THEN
      RAISE EXCEPTION 'catalog: the creator of a proposal is one of its authors'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW."productId" IS DISTINCT FROM OLD."productId"
     OR NEW."siteId" IS DISTINCT FROM OLD."siteId"
     OR NEW."locale" IS DISTINCT FROM OLD."locale"
     OR NEW."createdById" IS DISTINCT FROM OLD."createdById"
     OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN
    RAISE EXCEPTION 'catalog: a proposal keeps its product, site, locale and creator'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."version" <> OLD."version" + 1 THEN
    RAISE EXCEPTION 'catalog: every proposal change increments its version by one'
      USING ERRCODE = 'check_violation';
  END IF;
  content_changed :=
    NEW."proposedSummary" IS DISTINCT FROM OLD."proposedSummary"
    OR NEW."proposedDescription" IS DISTINCT FROM OLD."proposedDescription"
    OR NEW."reviewData" IS DISTINCT FROM OLD."reviewData"
    OR NEW."sourceRef" IS DISTINCT FROM OLD."sourceRef"
    OR NEW."sourceSha256" IS DISTINCT FROM OLD."sourceSha256";
  -- A revision returns the proposal to REVIEW_PENDING, with new content or unchanged content
  -- (a resubmission after a request for changes); the CHECK clears the decision fields.
  IF NEW."status" = 'REVIEW_PENDING' THEN
    RETURN NEW;
  END IF;
  IF content_changed THEN
    RAISE EXCEPTION 'catalog: a changed proposal returns to REVIEW_PENDING'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" IN ('APPROVED', 'CHANGES_REQUESTED') THEN
    IF OLD."status" <> 'REVIEW_PENDING' THEN
      RAISE EXCEPTION 'catalog: a decision needs a proposal in review'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."decidedById" = ANY (OLD."authorIds") OR NEW."authorIds" IS DISTINCT FROM OLD."authorIds" THEN
      RAISE EXCEPTION 'catalog: separation of duties: an author cannot decide on the proposal'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'catalog: a proposal change is either a revision or a decision'
    USING ERRCODE = 'check_violation';
END
$fn$;
CREATE TRIGGER "ProductContentProposal_guard" BEFORE INSERT OR UPDATE ON "ProductContentProposal"
  FOR EACH ROW EXECUTE FUNCTION catalog_content_proposal_guard();

-- An event names the proposal version it produced and, for a decision, an actor who is not an
-- author of the revision (checked against the proposal as it is, before its status changes).
CREATE FUNCTION catalog_content_proposal_event_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
DECLARE
  p RECORD;
BEGIN
  SELECT "status", "version", "authorIds" INTO p
    FROM "ProductContentProposal" WHERE "id" = NEW."proposalId";
  IF NEW."action" IN ('APPROVED', 'CHANGES_REQUESTED') THEN
    IF p."status" IS DISTINCT FROM 'REVIEW_PENDING' THEN
      RAISE EXCEPTION 'catalog: a decision needs a proposal in review'
        USING ERRCODE = 'check_violation';
    END IF;
    IF NEW."actorUserId" = ANY (p."authorIds") THEN
      RAISE EXCEPTION 'catalog: separation of duties: an author cannot decide on the proposal'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW."action" = 'CREATED' AND NEW."proposalVersion" <> 1 THEN
    RAISE EXCEPTION 'catalog: the CREATED event records version 1'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."action" <> 'CREATED' AND NEW."proposalVersion" <> p."version" + 1 THEN
    RAISE EXCEPTION 'catalog: an event records the version its change produces'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$fn$;
CREATE TRIGGER "ProductContentProposalEvent_guard" BEFORE INSERT ON "ProductContentProposalEvent"
  FOR EACH ROW EXECUTE FUNCTION catalog_content_proposal_event_guard();

-- The review history is append-only, for every role (the privileges below are the first line).
CREATE FUNCTION catalog_content_proposal_event_append_only() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  RAISE EXCEPTION 'catalog: the proposal history is append-only'
    USING ERRCODE = 'insufficient_privilege';
END
$fn$;
CREATE TRIGGER "ProductContentProposalEvent_append_only"
  BEFORE UPDATE OR DELETE ON "ProductContentProposalEvent"
  FOR EACH ROW EXECUTE FUNCTION catalog_content_proposal_event_append_only();
CREATE TRIGGER "ProductContentProposalEvent_no_truncate" BEFORE TRUNCATE ON "ProductContentProposalEvent"
  FOR EACH STATEMENT EXECUTE FUNCTION catalog_content_proposal_event_append_only();

-- ===========================================================================================
-- Part 3: privileges (dp_app gets SELECT, INSERT, UPDATE, DELETE by default, ADR-012A)
-- ===========================================================================================

-- History rows are never changed or removed; proposals are never deleted (they are revised).
REVOKE UPDATE, DELETE ON TABLE "ProductContentProposalEvent" FROM dp_app;
REVOKE DELETE ON TABLE "ProductContentProposal" FROM dp_app;
